import{_ as s,a0 as u,w as i,s as l,I as r,x as e,a1 as p,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在ubuntu桌面配置一個網絡打印機和掃描儀 | LCTT x X-CMD","titleTemplate":false,"description":"如何在ubuntu桌面配置一個網絡打印機和掃描儀 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在ubuntu桌面配置一個網絡打印機和掃描儀 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在ubuntu桌面配置一個網絡打印機和掃描儀 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140821 How to configure a network printer and scanner on Ubuntu desktop","title":"如何在ubuntu桌面配置一個網絡打印機和掃描儀","tag":"201411","desc":""},"relativePath":"201411/20140821 How to configure a network printer and scanner on Ubuntu desktop.md","filePath":"[post].md"}'),d={name:"201411/20140821 How to configure a network printer and scanner on Ubuntu desktop.md"};function g(m,t,c,f,b,k){const n=u("Link");return i(),l("div",null,[t[25]||(t[25]=r("h1",{id:"如何在ubuntu桌面配置一個網絡打印機和掃描儀",tabindex:"-1"},[e("如何在ubuntu桌面配置一個網絡打印機和掃描儀 "),r("a",{class:"header-anchor",href:"#如何在ubuntu桌面配置一個網絡打印機和掃描儀","aria-label":"Permalink to “如何在ubuntu桌面配置一個網絡打印機和掃描儀”"},"​")],-1)),r("p",null,[t[1]||(t[1]=e("在",-1)),p(n,{href:"http://linux.cn/article-4139-1.html"},{default:o(()=>[...t[0]||(t[0]=[e("之前的文章中",-1)])]),_:1}),t[2]||(t[2]=e(", 我們討論過如何在Linux服務器安裝各種各樣的打印機（當然也包括網絡掃描儀）。今天我們將來處理另一端：如何通過桌面客户端來訪問網絡打印機/掃描儀。",-1))]),t[26]||(t[26]=r("h3",{id:"網絡環境",tabindex:"-1"},[e("網絡環境 "),r("a",{class:"header-anchor",href:"#網絡環境","aria-label":"Permalink to “網絡環境”"},"​")],-1)),t[27]||(t[27]=r("p",null,"在這個安裝教程中，我們的服務器（Debian Wheezy 7.2版本）的IP地址是192.168.0.10，我們的客户端(Ubuntu 12.04版本)的IP地址是192.168.0.105.注意這兩台機器是在同一個網段（192.168.0.0/24).如果我們想允許打印機訪問其它網段，我們需要在服務器上修改cupsd.conf文件的以下部分：",-1)),t[28]||(t[28]=r("pre",null,[r("code",null,`<Location />
  Order allow,deny
  Allow localhost
  Allow from XXX.YYY.ZZZ.*
</Location>
`)],-1)),t[29]||(t[29]=r("p",null,"（在上述例子中，我們授予打印機從本地或者任何系統能夠訪問打印機，這些系統的IPv4地址以XXX.YYY.ZZZ開始。",-1)),r("p",null,[t[4]||(t[4]=e("為了驗證哪些打印機可以在我們的服務器上適用，我們也可以在服務器上使用lpstat命令，或者瀏覽網頁",-1)),p(n,{href:"https://192.168.0.10:631/printers"},{default:o(()=>[...t[3]||(t[3]=[e("https://192.168.0.10:631/printers",-1)])]),_:1}),t[5]||(t[5]=e(" page.",-1))]),t[30]||(t[30]=a(`<pre><code>root@debian:~# lpstat -a 
</code></pre><hr><pre><code>EPSON_Stylus_CX3900 accepting requests since Mon 18 Aug 2014 10:49:33 AM WARST
PDF accepting requests since Mon 06 May 2013 04:46:11 PM WARST
SamsungML1640Series accepting requests since Wed 13 Aug 2014 10:13:47 PM WARST
</code></pre><p><img src="https://farm4.staticflickr.com/3903/14777969919_7b7b25a4a4_z.jpg" alt=""></p><h3 id="在ubuntu桌面安裝網絡打印機" tabindex="-1">在Ubuntu桌面安裝網絡打印機 <a class="header-anchor" href="#在ubuntu桌面安裝網絡打印機" aria-label="Permalink to “在Ubuntu桌面安裝網絡打印機”">​</a></h3><p>在我們的Ubuntu 12.04的客户端，我們將打開&quot;Printing&quot;菜單(Dash -&gt; Printing).你會注意到在其它發行版中，這個名字也許會有一點差別（例如會叫做&quot;Printers&quot; 或者 &quot;Print &amp; Fax&quot;）:</p><p><img src="https://farm4.staticflickr.com/3837/14964314992_d8bd0c0d04_o.png" alt=""></p><p>還沒有打印機添加到我們的客户端：</p><p><img src="https://farm4.staticflickr.com/3887/14941655516_80430529b5_o.png" alt=""></p><p>下面是在Ubuntu桌面客户端安裝一台網絡打印機的一些步驟。</p><p><strong>1)</strong> “Add”按鈕將彈出 &quot;New Printer&quot; 菜單。我們將選擇&quot;Network printer&quot; -&gt; &quot;Find Network Printer&quot;並輸入我們服務器的IP地址，接着點擊&quot;Find&quot;:</p><p><img src="https://farm6.staticflickr.com/5581/14777977730_74c29a99b2_z.jpg" alt=""></p><p><strong>2)</strong> 在最下面我們將會看到可使用的打印機的名稱。我們來選擇這台三星打印機並按&quot;Forward&quot;:</p><p><img src="https://farm6.staticflickr.com/5585/14941655566_c1539a3ea0.jpg" alt=""></p><p><strong>3)</strong> 我們將會被要求填寫一些關於我們打印機的信息。當我們輸入完成時，將點擊 &quot;Apply&quot;按鈕。</p><p><img src="https://farm4.staticflickr.com/3908/14941655526_0982628fc9_z.jpg" alt=""></p><p><strong>4)</strong> 我們接下來將被詢問是否打印一張測試頁。讓我們點擊&quot;Print test page&quot;吧:</p><p><img src="https://farm4.staticflickr.com/3853/14964651435_cc83bb35aa.jpg" alt=""></p><p>這個打印任務將被創建為本地id 2：</p><p><img src="https://farm6.staticflickr.com/5562/14777977760_b01c5338f2.jpg" alt=""></p><p>5)適用我們服務器上的CUPS網絡藉口，我們可以觀察到打印任務已經提交成功了（打印機 -&gt; SamsungML1640系列 -&gt; 顯示完成任務):</p><p><img src="https://farm4.staticflickr.com/3887/14778110127_359009cbbc_z.jpg" alt=""></p><p>我們也可以通過在打印機服務器上運行以下命令顯示同樣信息：</p><pre><code> root@debian:~# cat /var/log/cups/page_log | grep -i samsung 
</code></pre><hr><pre><code>SamsungML1640Series root 27 [13/Aug/2014:22:15:34 -0300] 1 1 - localhost Test Page - -
SamsungML1640Series gacanepa 28 [18/Aug/2014:11:28:50 -0300] 1 1 - 192.168.0.105 Test Page - -
SamsungML1640Series gacanepa 29 [18/Aug/2014:11:45:57 -0300] 1 1 - 192.168.0.105 Test Page - -
</code></pre><p>這個page_log日誌顯示每一頁被打印過的信息，只包括哪些用户發送這些打印任務，打印日期&amp;時間，以及客户端的IPv4地址。</p><p>要安裝Epson噴墨和PDF打印機，我們只需重複第1-5的步驟即可，並每一次選擇左邊的打印隊列。例如，在下圖中選擇PDF打印機：</p><p><img src="https://farm4.staticflickr.com/3926/14778046648_c094c8422c_o.png" alt=""></p>`,29)),r("p",null,[t[7]||(t[7]=e("然而，請注意到根據",-1)),p(n,{href:"http://www.cups-pdf.de/documentation.shtml"},{default:o(()=>[...t[6]||(t[6]=[e("CUPS-PDF 文檔中",-1)])]),_:1}),t[8]||(t[8]=e("，根據默認：",-1))]),t[31]||(t[31]=a(`<blockquote><p>PDF文件將會被放置在打印作業的所有者命名的子目錄內。在這個案例中，打印作業的所有者不能被識別（i.e.不會存在服務器中）輸出的內容被放置在匿名操作的文件中。</p></blockquote><p>這些默認的文件夾可以通過改變在/etc/cups/cups-pdf目錄中的<strong>Out</strong>值和<strong>AnonDirName</strong>變量來修改。這裏，\${HOME}被擴展到用户的家目錄中：</p><pre><code>Out \${HOME}/PDF
AnonDirName /var/spool/cups-pdf/ANONYMOUS
</code></pre><h3 id="網絡打印實例" tabindex="-1">網絡打印實例 <a class="header-anchor" href="#網絡打印實例" aria-label="Permalink to “網絡打印實例”">​</a></h3><h4 id="實例-1" tabindex="-1">實例 #1 <a class="header-anchor" href="#實例-1" aria-label="Permalink to “實例 #1”">​</a></h4><p>從Ubuntu12.04中打印，通常在本地用gacanepa（具有相同名字存在打印機服務器上）。</p><p><img src="https://farm4.staticflickr.com/3845/14778046698_57b6e552f3_z.jpg" alt=""></p><p>打印到PDF打印機之後，讓我們來檢查打印機服務器上的/home/gacanepa/PDF目錄下的內容：</p><pre><code>root@debian:~# ls -l /home/gacanepa/PDF 
</code></pre><hr><pre><code>total 368
-rw------- 1 gacanepa gacanepa 279176 Aug 18 13:49 Test_Page.pdf
-rw------- 1 gacanepa gacanepa   7994 Aug 18 13:50 Untitled1.pdf
-rw------- 1 gacanepa gacanepa  74911 Aug 18 14:36 Welcome_to_Conference_-_Thomas_S__Monson.pdf
</code></pre><p>這個PDF文件被創建時的，權限已經設置為600(-rw-------)，這意味着只有打印任務的所有者(在這個例子中是gacanepa )可以訪問它們。我們可以通過修改the /etc/cups/cups-pdf.conf文件<strong>UserUMask</strong>變量的值來改變這種行為。例如，0033的umask值將可以使PDF打印者以及其它所有者擁有創建文件的權限，但是隻讀權限也會賦予給其它所有者。</p><pre><code> root@debian:~# grep -i UserUMask /etc/cups/cups-pdf.conf 
</code></pre><hr><pre><code>### Key: UserUMask
UserUMask 0033
</code></pre><p>對於那些不熟悉umask（有名用户文件創建模式掩碼），它作為一組可以用於控制那些為新文件創建時修改默認權限。給予特定的umask值，在計算最終文件的許可權限時，在文件基本權限(0666)和umask的單項按位補碼之間進行按位布爾 AND 運算。因此，如果設置一個umask值為0033，那麼新文件默認的權限將不是（0033）AND 0666 = 644的值（文件擁有者具有讀/寫/執行的權限，其他人擁有隻讀權限）。</p><h3 id="實例-2" tabindex="-1">實例 #2 <a class="header-anchor" href="#實例-2" aria-label="Permalink to “實例 #2”">​</a></h3><p>在Ubuntu12.04執行打印，本地登錄用户為jdoe（同樣的帳號名稱但是服務器上是不存在的）。</p><p><img src="https://farm4.staticflickr.com/3907/14964315142_a71d8a8aef_z.jpg" alt=""></p><pre><code> root@debian:~# ls -l /var/spool/cups-pdf/ANONYMOUS 
</code></pre><hr><pre><code>total 5428
-rw-rw-rw- 1 nobody nogroup 5543070 Aug 18 15:57 Linux_-_Wikipedia__the_free_encyclopedia.pdf
</code></pre><p>這個PDF被創建時賦予的權限是666(-rw-rw-rw-)，這意味着每個人都可以訪問它們。我們可以通過編輯在/etc/cups/cups-pdf.conf文件中的<strong>AnonUMask</strong>值來改變這種行為。</p><p>在這一點上，你也許會疑惑：為什麼同樣安裝一台網絡打印機，大多數（當然不是全部）當前的Linux桌面發行版都會內置一個&quot;打印到文件&quot;的功能來允許用户動態創建PDF文件？</p><p>使用一台網絡PDF打印機有以下好處：</p><ul><li><p>一個網絡打印機（任何類型的）允許你直接從命令列直接打印，無需首先打開文件。</p></li><li><p>在其它操作系統上安裝一個網絡客户端，一個PDF網絡打印機備件，於是系統管理員不必再單獨需要安裝PDF創建者實用程序（也避免了最終用户安裝這些工具存在的風險）。</p></li><li><p>網絡PDF打印機允許通過配置權限直接打印一個網絡共享，如我們所見的例子。</p></li></ul><h3 id="在ubuntu桌面安裝一個網絡掃描儀" tabindex="-1">在Ubuntu桌面安裝一個網絡掃描儀 <a class="header-anchor" href="#在ubuntu桌面安裝一個網絡掃描儀" aria-label="Permalink to “在Ubuntu桌面安裝一個網絡掃描儀”">​</a></h3>`,27)),r("p",null,[t[10]||(t[10]=e("這裏是通過Ubuntu桌面客户端安裝和訪問一台網絡掃描儀的一些步驟。假設網絡掃描儀服務器已經啓動並運行所述",-1)),p(n,{href:"http://xmodulo.com/2014/08/usb-network-printer-and-scanner-server-debian.html#scanner"},{default:o(()=>[...t[9]||(t[9]=[e("here",-1)])]),_:1}),t[11]||(t[11]=e(".",-1))]),t[32]||(t[32]=a(`<p><strong>1)</strong>讓我們第一步來檢查在我們的Ubuntu客户端主機上是否存在一台可用的掃描儀。沒有先前的安裝，你將會看到信息提示&quot;沒有識別到掃描儀.&quot; $ scanimage -L</p><p><img src="https://farm4.staticflickr.com/3906/14777977850_1ec7994324_z.jpg" alt=""></p><p><strong>2)</strong> 現在我們需要啓用saned進程，用來預裝Ubuntu桌面。要啓用它，我們需要編輯/etc/default/saned文件，並設置RUN變量為yes：</p><pre><code>$ sudo vim /etc/default/saned 
</code></pre><hr><pre><code># Set to yes to start saned
RUN=yes
</code></pre><p><strong>3)</strong> 讓我們編輯/etc/sane.d/net.conf文件，並在掃描儀安裝後添加服務器IP地址：</p><p><img src="https://farm6.staticflickr.com/5581/14777977880_c865b0df95_z.jpg" alt=""></p><p><strong>4)</strong> 重啓saned進程：</p><pre><code>$ sudo service saned restart 
</code></pre><p><strong>5)</strong> 現在讓我們來看看掃描儀是否可用： <img src="https://farm4.staticflickr.com/3839/14964651605_241482f856_z.jpg" alt=""></p><p>現在我們可以打開&quot;Simple Scan&quot;（或者其它掃描工具）並開始掃描文件。我們可以旋轉，修剪，和保存生成的圖片：</p><p><img src="https://farm6.staticflickr.com/5589/14777970169_73dd0e98e3_z.jpg" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>擁有一或多台網絡打印機或掃描儀在任何辦公和家庭網絡中都是非常方便適用的，並同時提供了許多好處。例舉如下：</p><ul><li><p>多用户（從不同的平台/地方）都能夠向打印機發送打印作業的隊列。</p></li><li><p>由於硬件共享達到了節約成本和維護的作用。</p></li></ul><p>我希望這篇文章可以幫助你更充分地利用這些有點。</p><hr>`,18)),r("p",null,[t[13]||(t[13]=e("via: ",-1)),p(n,{href:"http://xmodulo.com/2014/08/configure-network-printer-scanner-ubuntu-desktop.html"},{default:o(()=>[...t[12]||(t[12]=[e("http://xmodulo.com/2014/08/configure-network-printer-scanner-ubuntu-desktop.html",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=e("作者：",-1)),p(n,{href:"http://xmodulo.com/author/gabriel"},{default:o(()=>[...t[14]||(t[14]=[e("Gabriel Cánepa",-1)])]),_:1}),t[18]||(t[18]=e(" 譯者：",-1)),p(n,{href:"https://github.com/disylee"},{default:o(()=>[...t[15]||(t[15]=[e("disylee",-1)])]),_:1}),t[19]||(t[19]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[22]||(t[22]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[20]||(t[20]=[e("LCTT",-1)])]),_:1}),t[23]||(t[23]=e(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...t[21]||(t[21]=[e("Linux中國",-1)])]),_:1}),t[24]||(t[24]=e(" 榮譽推出",-1))])])}const h=s(d,[["render",g]]);export{T as __pageData,h as default};
